const dns = require('dns');
const util = require('util');
const lookup = util.promisify(dns.lookup);

(async () => {
    try {
        const result = await lookup('iot-mysql');
        msg.payload = {
            status: "✅ DNS解析成功",
            hostname: "iot-mysql",
            ip: result.address,
            family: result.family
        };
        node.send(msg);
    } catch (error) {
        msg.payload = {
            status: "❌ DNS解析失败",
            hostname: "iot-mysql",
            error: error.message
        };
        node.send(msg);
    }
})();

const net = require('net');

const socket = new net.Socket();
const timeout = 5000;

let isResolved = false;

const resolve = (result) => {
    if (!isResolved) {
        isResolved = true;
        msg.payload = result;
        node.send(msg);
    }
};

socket.setTimeout(timeout);

socket.on('connect', () => {
    socket.destroy();
    resolve({
        status: "✅ TCP连接成功",
        host: "iot-mysql",
        port: 3306,
        message: "MySQL端口可访问"
    });
});

socket.on('error', (error) => {
    resolve({
        status: "❌ TCP连接失败",
        host: "iot-mysql",
        port: 3306,
        error: error.message
    });
});

socket.on('timeout', () => {
    socket.destroy();
    resolve({
        status: "⏰ TCP连接超时",
        host: "iot-mysql",
        port: 3306,
        message: "连接超时，可能存在网络问题"
    });
});

socket.connect(3306, 'iot-mysql');

// 使用mysql2模块直接测试连接
const mysql = global.get('mysql') || require('mysql2');

const config = {
    host: 'iot-mysql',
    port: 3306,
    user: 'root',
    password: 'iot123456',
    database: 'IoTDataCollection_Main',
    connectTimeout: 10000,
    acquireTimeout: 10000
};

const connection = mysql.createConnection(config);

connection.connect((error) => {
    if (error) {
        msg.payload = {
            status: "❌ MySQL连接失败",
            config: {
                host: config.host,
                port: config.port,
                database: config.database
            },
            error: error.message,
            errorCode: error.code
        };
    } else {
        msg.payload = {
            status: "✅ MySQL连接成功",
            config: {
                host: config.host,
                port: config.port,
                database: config.database
            },
            message: "数据库连接正常"
        };

        // 执行简单查询测试
        connection.query('SELECT 1 as test', (queryError, results) => {
            if (!queryError) {
                msg.payload.queryResult = results;
                msg.payload.queryStatus = "查询执行成功";
            }
            connection.end();
            node.send(msg);
        });
        return;
    }
    node.send(msg);
});
